// Legendary shrines (pure): the ASCII layouts of LEGENDARY_SHRINES.md, generated by scripts/gen-shrines.py into
// data/world/shrines.json. A region's legendary site points at one (`shrine`); ValleyMap stamps it onto the map
// (terrain + walls + pillars, statues, altar…) with the anchor (arena centre, else the altar) on the site's tile.
import shrinesJson from '../data/world/shrines.json';

/** Terrain names (keys of T in core/map/tiles.ts) used by a shrine's floor, rune lines, hazard ground… */
export interface ShrineMaterials { floor: string; rune: string; x: string; star: 'crystal' | 'torch'; ground?: string }

export interface ShrineDef {
  id: string;
  legend: string;
  tier: 1 | 2 | 3 | 4;
  /** region id, or 'instanced' (a plane of its own) */
  region: string;
  x: number;
  y: number;
  /** layout cell placed on (x, y) */
  anchor: [number, number];
  /** arena radius in tiles around the anchor (0 = no fight here) */
  arena: number;
  /** blockers allowed inside the arena (the altar that sinks when the fight starts, rune stones as cover) */
  cover: string;
  materials: ShrineMaterials;
  rows: string[];
}

export const SHRINES = new Map<string, ShrineDef>((shrinesJson as unknown as ShrineDef[]).map((s) => [s.id, s]));

/** Layout characters you can walk on (`%` once smashed, `^` once the seal opens). */
export const SHRINE_WALK = new Set([...',.:=xwP+&12%^']);
/** Characters that become a map object. */
export const SHRINE_OBJECTS = new Set([...'OoS*AT&12B']);

/**
 * Layout char at a layout cell, or null outside the footprint. Cells holding the fill char (the corner char) count
 * only inside the layout's inscribed ellipse or right next to ground you walk on: sea, forest or cliff around a
 * shrine fades into the map instead of ending in a square, while every wall / shore of the court stays closed.
 */
export function shrineCell(s: ShrineDef, lx: number, ly: number): string | null {
  const row = s.rows[ly];
  if (!row || lx < 0 || lx >= row.length) return null;
  const ch = row[lx];
  if (ch !== s.rows[0][0]) return ch;
  const w = row.length, h = s.rows.length;
  const e = ((lx + 0.5 - w / 2) / (w / 2)) ** 2 + ((ly + 0.5 - h / 2) / (h / 2)) ** 2;
  if (e <= 1) return ch;
  for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) if (SHRINE_WALK.has(s.rows[ly + dy]?.[lx + dx] ?? '')) return ch;
  return null;
}

/** Map-tile rectangle [x0, y0, x1, y1] (inclusive) a shrine covers when its anchor stands on (x, y). */
export function shrineBounds(s: ShrineDef, x = s.x, y = s.y): [number, number, number, number] {
  const x0 = x - s.anchor[0], y0 = y - s.anchor[1];
  return [x0, y0, x0 + s.rows[0].length - 1, y0 + s.rows.length - 1];
}

/** Every stamped cell: map tile + layout char. */
export function* shrineCells(s: ShrineDef, x = s.x, y = s.y): Generator<{ tx: number; ty: number; ch: string }> {
  const [x0, y0] = shrineBounds(s, x, y);
  for (let ly = 0; ly < s.rows.length; ly++) for (let lx = 0; lx < s.rows[ly].length; lx++) {
    const ch = shrineCell(s, lx, ly);
    if (ch !== null) yield { tx: x0 + lx, ty: y0 + ly, ch };
  }
}

/** Blockers inside the arena (radius − 1 around the anchor) other than the allowed cover. Empty = a clean arena. */
export function arenaBlockers(s: ShrineDef): { x: number; y: number; ch: string }[] {
  const out: { x: number; y: number; ch: string }[] = [];
  if (!s.arena) return out;
  const [ax, ay] = s.anchor;
  s.rows.forEach((row, y) => [...row].forEach((ch, x) => {
    if (Math.hypot(x - ax, y - ay) <= s.arena - 1 && !SHRINE_WALK.has(ch) && !s.cover.includes(ch)) out.push({ x, y, ch });
  }));
  return out;
}

/** Layout cell of the first `ch` (the altar 'A', the player's ritual spot 'P'…). */
export function shrineFind(s: ShrineDef, ch: string): [number, number] | null {
  for (let y = 0; y < s.rows.length; y++) {
    const x = s.rows[y].indexOf(ch);
    if (x >= 0) return [x, y];
  }
  return null;
}
